document.addEventListener('change',e=>{let el=e.target;if(!el.matches('[data-showcase-slot]'))return;let i=Number(el.dataset.showcaseSlot),p=collectorProfile(),id=el.value===''?null:Number(el.value);if(id!==null&&!state.owned.some(o=>o.id===id))return;if(id!==null&&p.showcase.some((x,j)=>x===id&&j!==i))return toast('Car already on display');p.showcase[i]=id;save();drawShowroom();toast('Showroom updated')});
document.addEventListener('click',e=>{let b=e.target.closest('[data-wish-id]');if(!b)return;let id=Number(b.dataset.wishId),p=collectorProfile();p.wishlist=p.wishlist.includes(id)?p.wishlist.filter(x=>x!==id):[...p.wishlist,id];save();drawWishlist();$('profileNumbers').lastElementChild.querySelector('strong').textContent=p.wishlist.length});
window.cardexShowAuth=()=>page('auth');window.cardexShowGame=()=>page('boosters');
function page(name){if(name!=='auth'&&!window.cardexCloudReady){name='auth'}document.querySelectorAll('.page').forEach(s=>s.classList.toggle('active',s.id===name));document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='garage')drawCollection();if(name==='duel')drawDuel();if(name==='profile')drawProfile();if(name==='duel')window.cardexOnlineRefresh?.();if(name==='boosters')drawPacks();stats();window.scrollTo(0,0)}document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page)page(b.dataset.page);if(b.dataset.pack!==undefined)openPack(Number(b.dataset.pack));if(b.dataset.packBulk!==undefined)openPack(Number(b.dataset.packBulk),Number(b.dataset.quantity),true);if(b.dataset.star!==undefined){let id=Number(b.dataset.star);state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();drawCollection()}if(b.dataset.salvage){if(window.cardexServerGameReady){let [id,finish]=b.dataset.salvage.split('|');if(!confirm('Recycle one or more spare copies of this model and finish? Cards used in Showdown are protected.'))return;return window.cardexRecycleServerDuplicates?.(Number(id),finish)}let [id,finish]=b.dataset.salvage.split('|'),copies=state.owned.filter(o=>o.id===Number(id)&&o.finish===finish);if(copies.length<2)return toast('Keep at least one copy');let index=state.owned.findIndex(o=>o.id===Number(id)&&o.finish===finish);state.owned.splice(index,1);let reward=[10,20,35,60,100,200][tiers.indexOf(cars[Number(id)].rarity)];state.credits+=reward;save();drawCollection();stats();toast(`Recycled duplicate · +${reward} credits`)}if(b.dataset.claim!==undefined){if(window.cardexServerGameReady)return window.cardexClaimServerAchievement?.(Number(b.dataset.claim));let i=Number(b.dataset.claim),a=achievements[i];if(a&&!state.achievements.includes(i)&&a[2](state)){state.credits+=a[3];state.achievements.push(i);save();drawProfile();stats();toast(`Achievement unlocked · +${a[3]} credits`)}}});$('nextReveal').onclick=nextReveal;$('revealCard').addEventListener('click',e=>{if(e.target.closest('.photo-credit'))return;nextReveal()});$('revealCard').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();nextReveal()}});$('skipReveal').onclick=()=>{if(reveal.length)showPackSummary()};$('showdownSearch').addEventListener('input',drawDuel);document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.inspect!==undefined)inspectCar(Number(b.dataset.inspect));if(b.hasAttribute('data-close-car'))closeCar();if(b.dataset.favoriteCar!==undefined){let id=Number(b.dataset.favoriteCar);state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();drawCollection();inspectCar(state.owned.findIndex(x=>x.id===id))}if(b.dataset.useCar!==undefined){chosenChallenger=Number(b.dataset.useCar);closeCar();page('duel');$('showdownPreview').scrollIntoView({behavior:'smooth',block:'center'})}if(b.dataset.recycleCar!==undefined){if(window.cardexServerGameReady){let index=Number(b.dataset.recycleCar),o=state.owned[index];if(!o)return toast('Card unavailable');if(!confirm('Recycle spare copies of this model and finish? Showdown cards are protected.'))return;closeCar();return window.cardexRecycleServerDuplicates?.(o.id,o.finish)}let index=Number(b.dataset.recycleCar),o=state.owned[index];if(!o)return;let copies=state.owned.filter(x=>x.id===o.id&&x.finish===o.finish).length;if(copies<2)return toast('Keep at least one copy');if(!confirm('Recycle this duplicate permanently for credits?'))return;let reward=duplicateReward(o.id);state.owned.splice(index,1);state.credits+=reward;save();closeCar();drawCollection();stats();toast('Duplicate recycled · +'+reward+' credits')}});document.addEventListener('click',e=>{let b=e.target.closest('[data-challenger]');if(b){chosenChallenger=Number(b.dataset.challenger);drawDuel();$('showdownPreview').scrollIntoView({behavior:'smooth',block:'center'})}});document.addEventListener('click',e=>{const b=e.target.closest('[data-buy-tickets]');if(!b||b.disabled)return;const quantity=Number(b.dataset.buyTickets);if(window.cardexServerGameReady)return window.cardexBuyServerTickets?.(quantity);toast('Ticket purchases require a server connection')});['search','rarityFilter','sort','driveFilter','countryFilter','finishFilter'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>drawCollection()));$('recycleAllDuplicates').onclick=recycleAllSpares;$('groupCopies').onclick=()=>{groupCopies=!groupCopies;drawCollection()};$('duplicates').onclick=()=>{dupOnly=!dupOnly;$('duplicates').textContent=dupOnly?'✓ Duplicates only':'Duplicates only';drawCollection()};$('countryFilter').innerHTML+=[...new Set(cars.map(c=>c.country))].sort().map(c=>'<option>'+c+'</option>').join('');setInterval(stats,30000);drawPacks();stats();

// Real car photography from Wikipedia's freely accessible page images.
// Each image links to its Wikimedia Commons file page for attribution and license details.
const photoTitles=["Toyota AE86","Honda Civic (fifth generation)","Volkswagen Golf Mk2","Ford Fiesta ST","Peugeot 205","Mazda MX-5 (NA)","Volkswagen Golf Mk7","Subaru Impreza (first generation)","BMW M3","Renault Clio V6 Renault Sport","Mazda RX-7","Mitsubishi Lancer Evolution","BMW M3","Honda NSX (first generation)","Audi RS 2 Avant","Nissan Skyline GT-R","Porsche 911 GT3","Lancia Delta S4","Lexus LFA","Ferrari F40","Porsche Carrera GT","Bugatti Veyron","Mercedes-Benz CLK GTR","McLaren F1 GTR","Ferrari 250 GTO","Porsche 917"];
photoTitles.push(...["Toyota Supra","Nissan Silvia","Honda S2000","Nissan 350Z","Toyota GR Yaris","Toyota Celica GT-Four","Subaru BRZ","Mitsubishi GTO","Nissan 300ZX","Honda Integra","Toyota MR2","Mazda RX-8","Nissan GT-R","Honda Civic Type R","BMW M3","BMW M5","BMW M4","Mercedes-Benz 190E","Mercedes-AMG GT","Audi Quattro","Audi R8","Volkswagen Scirocco","Porsche 930","Porsche 918 Spyder","Porsche 959","Porsche 911 GT1","Ferrari 458","Enzo Ferrari","LaFerrari","Lamborghini Countach","Lamborghini Murciélago","Lamborghini Huracán","Lancia Stratos","Alfa Romeo Giulia","Pagani Zonda","Pagani Huayra","McLaren 720S","McLaren P1","Lotus Elise","Lotus Exige","Aston Martin DBS","Jaguar XJ220","Ford Mustang","Ford GT","Ford GT","Chevrolet Corvette C6","Chevrolet Corvette C8","Dodge Viper","Dodge Challenger","AC Cobra","Renault 5 Turbo","Peugeot 206 WRC","Citroën DS3 WRC","Bugatti Chiron","Koenigsegg Agera","Koenigsegg Jesko","Volvo 850","Hyundai i30 N","Kia Stinger","Rimac Nevera"]);
photoTitles.push(...["Ferrari F40","Ruf CTR","RAUH-Welt Begriff","Lamborghini Huracán STO","Mercedes-Benz G 63 AMG 6x6","Bugatti La Voiture Noire","Lamborghini Veneno","Aston Martin Valkyrie","McLaren Speedtail","Pagani Zonda"]);
if(photoTitles.length!==cars.length){console.error('CARDEX photo mapping mismatch:',photoTitles.length,cars.length)}
const photoCache=new Map();
let photoLoading=false;
function photoNodes(){return [...document.querySelectorAll('[data-car-photo]')];}
function paintPhotos(){
 for(const node of photoNodes()){
  const data=photoCache.get(Number(node.dataset.carPhoto));
  if(!data || node.dataset.loadedPhoto===data.src)continue;
  node.dataset.loadedPhoto=data.src;
  node.classList.add('has-photo');
  node.innerHTML='<img loading="lazy" decoding="async" alt="" src="'+data.src+'">';
  const a=document.createElement('a');a.className='photo-credit';a.href=data.credit;a.target='_blank';a.rel='noopener noreferrer';a.textContent='IMAGE SOURCE ↗';a.title='View original image and licensing information';node.appendChild(a);
  node.querySelector('img').addEventListener('error',()=>{node.classList.remove('has-photo');node.textContent=node.dataset.fallback||'🚗';});
 }
}
async function loadCarPhotos(){
 if(photoLoading)return;photoLoading=true;
 try{
  let catalog=[];try{const res=await fetch('./car-images.json',{cache:'no-cache'});if(res.ok){const data=await res.json();if(Array.isArray(data.cars))catalog=data.cars}}catch(e){console.warn('Image catalog unavailable, using built-in references',e)}
  const titleById=new Map(),pinned=new Set();
  for(const entry of catalog){if(!Number.isInteger(entry.id)||entry.id<0||entry.id>=cars.length)continue;
    if(typeof entry.src==='string'&&/^https:\/\//.test(entry.src)&&typeof entry.credit==='string'&&/^https:\/\//.test(entry.credit)){photoCache.set(entry.id,{src:entry.src,credit:entry.credit});pinned.add(entry.id)}
    else if(typeof entry.article==='string'&&entry.article.trim())titleById.set(entry.id,entry.article.trim());
  }
  const groups=[];for(let k=0;k<photoTitles.length;k+=12)groups.push(photoTitles.slice(k,k+12).map((title,j)=>({title:titleById.get(k+j)||title,id:k+j})).filter(x=>!pinned.has(x.id)));paintPhotos();
  await Promise.all(groups.map(async group=>{
   try{
    if(!group.length)return;const titles=[...new Set(group.map(x=>x.title))];
    const api='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&redirects=1&prop=pageimages&piprop=thumbnail%7Cname&pithumbsize=850&titles='+encodeURIComponent(titles.join('|'));
    const response=await fetch(api);if(!response.ok)throw Error('Image request failed');
    const json=await response.json();const byTitle=new Map(Object.values(json.query?.pages||{}).map(p=>[p.title,p]));
    const normalized=new Map((json.query?.normalized||[]).map(x=>[x.from,x.to]));
    const redirects=new Map((json.query?.redirects||[]).map(x=>[x.from,x.to]));
    for(const entry of group){
     let title=normalized.get(entry.title)||entry.title;title=redirects.get(title)||title;
     const page=byTitle.get(title);if(!page?.thumbnail?.source)continue;
     const filename=page.pageimage;
     photoCache.set(entry.id,{src:page.thumbnail.source,credit:filename?'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(filename.replace(/ /g,'_')):'https://en.wikipedia.org/wiki/'+encodeURIComponent(title.replace(/ /g,'_'))});
    }
    paintPhotos();
   }catch(err){console.warn('Some car photographs unavailable',err)}
  }));
  paintPhotos();
 }catch(e){console.warn('Car photographs unavailable; keeping placeholders.',e)}
 finally{photoLoading=false}
}
