/* Modal accessibility: initial focus, Escape, tab containment, and focus restoration. */
(()=>{
 const overlays=['carModal','revealModal'].map(id=>document.getElementById(id));
 const origins=new WeakMap();
 const focusables=modal=>[...modal.querySelectorAll('button:not([disabled]):not([hidden]),[href],input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length&&!el.closest('[hidden]'));
 const observer=new MutationObserver(records=>{for(const rec of records){const modal=rec.target;if(!overlays.includes(modal))continue;
  if(modal.classList.contains('open')){origins.set(modal,document.activeElement);requestAnimationFrame(()=>{if(modal.classList.contains('open'))(focusables(modal)[0]||modal).focus()})}
  else{const previous=origins.get(modal);if(previous?.isConnected)requestAnimationFrame(()=>previous.focus({preventScroll:true}))}
 }});
 overlays.forEach(m=>{m.setAttribute('tabindex','-1');observer.observe(m,{attributes:true,attributeFilter:['class']})});
 document.addEventListener('keydown',e=>{
  const modal=overlays.findLast(m=>m.classList.contains('open'));if(!modal)return;
  if(e.key==='Escape'){e.preventDefault();if(modal.id==='carModal')closeCar();else if($('packSummary').hidden)showPackSummary();else closeReveal();return}
  if(e.key!=='Tab')return;
  const list=focusables(modal);if(!list.length){e.preventDefault();modal.focus();return}
  const first=list[0],last=list[list.length-1];
  if(e.shiftKey&&(document.activeElement===first||!modal.contains(document.activeElement))){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){e.preventDefault();first.focus()}
 });
 overlays.forEach(modal=>modal.addEventListener('click',e=>{if(e.target===modal){if(modal.id==='carModal')closeCar();else if($('packSummary').hidden)showPackSummary();else closeReveal()}}));
})();

/* Delegated feedback works for buttons rebuilt by game renders and on touch devices. */
(()=>{
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
  const layer=document.createElement('div');layer.id='cardexFxLayer';layer.setAttribute('aria-hidden','true');
  document.body.appendChild(layer);
  let lastBurst=0;
  document.addEventListener('pointerdown',e=>{
    const button=e.target.closest?.('button');
    if(!button||button.disabled||e.button!==0||reduced.matches)return;
    button.classList.remove('fx-hit');void button.offsetWidth;button.classList.add('fx-hit');
    setTimeout(()=>button.classList.remove('fx-hit'),300);
    if(Date.now()-lastBurst<85)return;
    lastBurst=Date.now();
    const rect=button.getBoundingClientRect();
    const x=Math.min(Math.max(e.clientX,rect.left),rect.right);
    const y=Math.min(Math.max(e.clientY,rect.top),rect.bottom);
    const special=button.matches('.primary,[data-pack],[data-pack-bulk],[data-claim],[data-salvage],#fight,#buyPack');
    const count=special?9:4;
    const color=special?'#ffd082':'#9dd7ff';
    const fragment=document.createDocumentFragment();
    for(let i=0;i<count;i++){
      const spark=document.createElement('i');spark.className='cardex-spark';
      const angle=2*Math.PI*i/count+(Math.random()-.5)*.35;
      const distance=(special?26:16)+Math.random()*(special?30:16);
      spark.style.setProperty('--spark-x',x+'px');
      spark.style.setProperty('--spark-y',y+'px');
      spark.style.setProperty('--spark-dx',Math.cos(angle)*distance+'px');
      spark.style.setProperty('--spark-dy',Math.sin(angle)*distance+'px');
      spark.style.setProperty('--spark-color',color);
      spark.style.setProperty('--spark-size',(3+Math.random()*4)+'px');
      fragment.appendChild(spark);
      spark.addEventListener('animationend',()=>spark.remove(),{once:true});
    }
    layer.appendChild(fragment);
  },{passive:true});
})();
